SELECT monthly_fee_bucket, unique_customers, total_monthly_fee FROM (SELECT CASE WHEN monthly_fee >= 241 THEN 'high' WHEN monthly_fee >= 90 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, COUNT(DISTINCT monthly_fee) AS unique_customers, SUM(monthly_fee) AS total_monthly_fee FROM subscriptions WHERE YEAR(end_date) = 2025 GROUP BY CASE WHEN monthly_fee >= 241 THEN 'high' WHEN monthly_fee >= 90 THEN 'mid' ELSE 'low' END) AS t WHERE total_monthly_fee >= 720 ORDER BY monthly_fee_bucket ASC, unique_customers ASC
